  ui_story_5083_50830100_2_dialog_content = "แต่พวกเขาแน่นอนมีความเชื่อมโยงกับความทรงจำของคุณ",
  ui_story_5083_50830100_3_dialog_content = "อาจเป็นอดีตที่คุณไม่สามารถยอมรับได้ หรือความเสียใจที่คุณไม่สามารถปล่อยมันไป—",
  ui_story_5083_50830100_4_dialog_content = "มันไม่มีเหตุผลสำหรับฉันเลย ดังนั้นเพียงหยุดมันไว้ ฉันไว้ใจคุณ ดังนั้นทำสิ่งที่คุณต้องทำเถอะ",
  ui_story_5083_50830100_5_dialog_content = "โอเค แล้วก็นอนลงและผ่อนคลายเถอะ... ขณะที่ฉันพยายามสัมผัสจิตใจของคุณ...",
  ui_story_5083_50830100_6_dialog_content = "ผู้ชาย ฉันรู้สึกง่วงมาก... นี่หมายความว่าฉันจะฝันฝันเดิมอีกครั้งเหรอ...?",
  ui_story_5083_50830100_7_dialog_content = "อ้อ, ลืมมันไป... ฉันแน่ใจว่าฉันจะไม่เป็นไรถ้ามีคุณอยู่รอบ ๆ...",
  ui_story_5083_50830100_8_dialog_content = "แค่นอนหลับ... แล้วเตรียมตัวพร้อมสู้...",
  ui_story_5083_50830100_9_dialog_content = "<color=#e8d9bb>เสียงนกหวีดแหลม สะท้อนอากาศ.</color>",
  ui_story_5083_50830100_10_dialog_content = "\"ฉันไม่รู้ว่าฉันถูกบอกอะไร!\"",
  ui_story_5083_50830100_11_dialog_content = "\"การฆ่าอิคลิพไซท์ไม่เคยเก่ามาก!\"",
  ui_story_5083_50830100_12_dialog_content = "ผู้ชายคนนี้...?",
  ui_story_5083_50830100_13_dialog_content = "\"เดินหน้า!\"",
  ui_story_5083_50830100_14_dialog_content = "\"March!\"",
  ui_story_5083_50830100_15_dialog_content = "สนามฝึกฝนเหรอ? นั่นก็เป็นเพลงฝึกฝนสมัยก่อนเช่นกัน...",
  ui_story_5083_50830100_16_dialog_content = "ทำไมถึงหยุดอยู่กลางทางแบบนั้น บาร์ตัน?! อย่าหยุดอยู่กลางทางแบบนั้นสิ!",
  ui_story_5083_50830100_17_dialog_content = "ด็อกก์... นั่นคุณรึ...?",
  ui_story_5083_50830100_18_dialog_content = "ยังครึ่งหลับครึ่งตื่นเหรอ? นั่นคือปัญหาของเธอนะ มิตร",
  ui_story_5083_50830100_19_dialog_content = "ด็อกจริงๆ แล้วสามารถผ่านบาร์ตันได้หรือ?!",
  ui_story_5083_50830100_20_dialog_content = "ไม่นะ นี่เพราะบาร์ตันหยุดทันที... นี่จะเป็นเรื่องที่ดีนะ",
  ui_story_5083_50830100_21_dialog_content = "บาร์ตัน คุณโง่! นี่คือสนามฝึกฝน ไม่ใช่สนามฝันเฟื่อง!",
  ui_story_5083_50830100_22_dialog_content = "เกิดอะไรขึ้นที่ทำให้เป็นทหารที่ดีที่สุดของกองทัพ? ถ้าคุณต้องการทำให้กองทัพของฉันเสียหายด้วยการเกียจคร้าน ก็ออกไปจากที่นี่เถอะ!",
