  ui_story_5083_50830100_55_dialog_content = "ถ้าฉันฝึกกับท่านครั้งหน้าได้ไหมครับ, รองผู้หมวด?",
  ui_story_5083_50830100_56_dialog_content = "แน่นอน ถ้าคุณสามารถตามทัน การฝึกฝนของฉันอาจจะหนักหน่อยบ้างเป็นครั้งคราว",
  ui_story_5083_50830100_57_dialog_content = "คุณช่วยมองทางนี้ได้ไหม ท่านรอง? ยิ้มให้กล้องหน่อย—",
