  ui_story_5083_50830100_59_dialog_content = "นี่เกี่ยวกับอะไร?",
  ui_story_5083_50830100_60_dialog_content = "ฉันได้ยินว่าเธอจบการศึกษาล่วงหน้าสองปี เหมือนคุณเลย ดูเหมือนว่าเรามี <color=#FFB400>นักเรียนซูเปอร์</color> อีกคนในทีมเรานะ",
  ui_story_5083_50830100_61_dialog_content = "แต่ไม่เหมือนคุณ คุณบาร์ตัน เธอมักจะถูกรายล้อมไปด้วยฝูงชนตลอดเวลา อาจจะหมายความว่าบุคลิกภาพของคุณต้องปรับปรุงบ้างเหรอ?",
  ui_story_5083_50830100_62_dialog_content = "... แต่ก็ยังคิดไม่ออกว่าคนอย่างเธอจะอยู่ในระดับเดียวกับคุณ",
  ui_story_5083_50830100_63_dialog_content = "คู่ต่อสู้ที่คู่ควร...",
  ui_story_5083_50830100_64_dialog_content = "โอ้? มีคนน่าสนใจเพิ่งปรากฏตัวขึ้น...",
  ui_story_5083_50830100_65_dialog_content = "ยังไงนะครับ?",
  ui_story_5083_50830100_66_dialog_content = "ไม่มีอะไร ตอนนี้ ช่วยหลีกทางได้มั้ย ฉันหิวมากเลย",
  ui_story_5083_50830100_67_dialog_content = "ด-ได้โปรดให้ฉันนั่งด้วยคุณ—",
  ui_story_5083_50830100_68_dialog_content = "เธอเป็นแค่ผู้มาใหม่ที่ไม่มีผลงานที่น่าพูดถึงเลย จากที่ฉันได้ยิน เธอได้รับความสนใจแบบนี้เพราะคณะกรรมการสนับสนุนเธอ",
  ui_story_5083_50830100_69_dialog_content = "ฮึ่ม, แค่ของแสดงสำหรับผู้บริหารเท่านั้น. เธอไม่ใช่คู่ต่อสู้สำหรับคุณ... และยิ่งไม่ใช่คู่ต่อสู้สำหรับฉัน!",
  ui_story_5083_50830100_70_dialog_content = "แสงนั่น...",
  ui_story_5083_50830100_71_dialog_content = "ว่าไง",
  ui_story_5083_50830100_72_dialog_content = "น่าสนใจ... เธอส่องแสงที่ไม่สามารถปฏิเสธได้ แสงที่ทำให้ฉันยากที่จะหันตาออกไป",
  ui_story_5083_50830100_73_dialog_content = "มีอะไรบางอย่างบอกฉันว่าในอนาคต หนึ่งในเราจะกลายเป็นจอมทัพ",
  ui_story_5083_50830100_74_dialog_content = "การตัดสินใจเลือกจอมทัพคนใหม่นั้นต้องใช้เวลามากกว่านี้... รอสักครู่, อย่าบอกฉันว่าคุณก็ถูกหลอกลวงด้วยแสงสว่างจากคนปลอมนั้นเหมือนกันเถอะ?",
  ui_story_5083_50830100_75_dialog_content = "... โอ้ ไม่! พวกนี้จะกินของดี ๆ ทั้งหมดถ้าเราไม่เข้าไปทันที!",
  ui_story_5083_50830100_76_dialog_content = "เฮ้ รอผมด้วยสิ!",
  ui_story_5083_50830100_77_dialog_content = "เราต้องสู้รบเพื่อแค่สองกระป๋องผลไม้ มื้ออาหารของเราบางครั้งมันน่ากลัวกว่าการฝึกฝนเลย",
  ui_story_5083_50830100_78_dialog_content = "ผมอยากได้แอปเปิล คุณล่ะ?",
  ui_story_5083_50830100_79_dialog_content = "ฉันไม่สนใจ แค่ให้ฉันอะไรก็ตามที่เหลือ... นี่!",
  ui_story_5083_50830100_80_dialog_content = "อุ๊บ!",
  ui_story_5083_50830100_81_dialog_content = "ดูสิ นั่นเด็กสาวที่ทำให้คุณแพ้ในการแข่งขันครั้งล่าสุด! ฉันได้ยินว่าเธอได้รับตำแหน่งเจ้าหน้าที่เทคแล้วนะ",
  ui_story_5083_50830100_82_dialog_content = "ไม่มีใครขอบทนำเลย คืนกระป๋องนั้นให้ฉันเดี๋ยวนี้!",
  ui_story_5083_50830100_83_dialog_content = "โอ้ ใช่ คุณคือคนนั้น... เอ่อ... อ่า ไม่เป็นไร! เกมดีๆนะ ทหารเพื่อน!",
  ui_story_5083_50830100_84_dialog_content = "นี่คือบาร์ตัน! คุณยังไม่เคยพยายามจำชื่อฉันเลยใช่ไหม?!",
  ui_story_5083_50830100_85_dialog_content = "ขอโทษนะ แค่เพราะฉันได้กำจัดคุณไปอย่างง่ายดาย พร้อมกับกลุ่มคนอื่นๆ",
  ui_story_5083_50830100_86_dialog_content = "เฮ้อ... คราวหน้าเราจะมาตัดสินผู้ชนะที่แท้จริงกัน, กรอนรู! จำคำพูดของฉันไว้เถอะ!",
  ui_story_5083_50830100_87_dialog_content = "เพียงแค่คุณรอ... ฉันจะชนะทุกอย่างคืนมาและมากกว่านั้น!",
  ui_story_5083_50830100_88_dialog_content = "ฉันไม่คิดว่าฉันเคยเห็นทหารล้างจานด้วยความรุนแรงมากขนาดนี้ บาร์ตัน ฉันต้องบอกว่าฉันประทับใจจริงๆ!",
  ui_story_5083_50830100_89_dialog_content = "... ผ-ผู้บัญชาการ!",
  ui_story_5083_50830100_90_dialog_content = "ตะวันคงจะขึ้นที่เมืองใต้ดินในเช้านี้ คุณมักจะเพียงล้างจานก่อนที่จะทิ้งไว้ แต่ตอนนี้คุณกำลังล้างจานเหมือนชีวิตของคุณขึ้นอยู่กับมัน",
  ui_story_5083_50830100_91_dialog_content = "บอกฉันสิ หัวเธอไปกระแทกอะไรมาหรือไง?",
  ui_story_5083_50830100_92_dialog_content = "ไม่เลยครับท่าน!",
  ui_story_5083_50830100_93_dialog_content = "ถ้างั้นบอกฉันหน่อยว่าตอนนี้มันกำลังเกิดอะไรขึ้น",
  ui_story_5083_50830100_94_dialog_content = "ฉันไม่รู้ครับ ฉันคิดว่าฉันต้องการวันหยุดเพื่อจัดการเรื่องราว!",
  ui_story_5083_50830100_95_dialog_content = "มีปัญหาในการสร้างสมดุลระหว่างงานและการพักผ่อนหรือไม่? หรือบางทีการต่อสู้ครั้งนั้นอาจจะมีผลกระทบต่อคุณมากเกินไป? คุณยังรู้สึกกลัวอยู่หรือไม่?",
  ui_story_5083_50830100_96_dialog_content = "ไม่, ครับ. นั่นไม่ใช่!",
  ui_story_5083_50830100_97_dialog_content = "แล้วก็ตั้งสติขึ้นมา ทหาร! แต่อีกครั้งนึง คุณก็ทำงานได้มากขึ้นเมื่อเป็นแบบนี้—",
  ui_story_5083_50830100_98_dialog_content = "ว้าว!",
  ui_story_5083_50830100_99_dialog_content = "แต่คุณยังคงอ่อนแอและมีช่องโหว่เต็มไปหมด! คุณจริง ๆ คิดว่าคุณจะเป็นดาวที่ส่องสว่างของกองพลที่ 2 หรือ?",
  ui_story_5083_50830100_100_dialog_content = "ครับผม, ผมไม่คิดเลยว่าจะถูกซุ่มโจมตีจากคนที่ผมไว้ใจ!",
  ui_story_5083_50830100_101_dialog_content = "ฉันสอนคุณให้รักษาการป้องกันอยู่เสมอและเตรียมอาวุธไว้ เพราะถ้าคุณทำตามที่ฉันสั่ง ฉันก็คงไม่สามารถที่จะทำให้คุณตกใจได้ง่ายๆ แบบนี้",
  ui_story_5083_50830100_102_dialog_content = "คุณดูไม่ค่อยเชื่อถือ แต่กลยุทธ์ใดก็ตามที่นำไปสู่ชัยชนะนั้นถูกต้อง! ไม่ใช่ปัญหาทั้งหมดที่ต้องการวิธีการโต้ตอบโดยตรง และในสงคราม ผลลัพธ์คือสิ่งที่สำคัญที่สุด",
  ui_story_5083_50830100_103_dialog_content = "ดูเหมือนว่าคุณยังต้องการการขัดเกลาเพิ่มเติมก่อนที่จะสามารถใช้ในการต่อสู้ได้",
  ui_story_5083_50830100_104_dialog_content = "กลับไปที่สนามฝึกฝนและให้ฉันอีกยี่สิบรอบด้วยความเร็วปกติของคุณ!",
  ui_story_5083_50830100_105_dialog_content = "... รับทราบ!",
  ui_story_5083_50830100_106_dialog_content = "เงียบมากที่นี่ ไม่ใช่หรือ? ฉันจะรู้ได้ยังไงว่าคุณกำลังวิ่งอยู่จริง ๆ ทหาร?! ฉันอยากได้ยินเสียงเพลงของคุณที่ร้องดัง ๆ!",
  ui_story_5083_50830100_107_dialog_content = "ครับ!",
