  ui_story_5083_50830200_32_dialog_content = "<color=#e8d9bb>อยู่ ๆ คนหนึ่งก็พุ่งผ่านทั้งสองคน ทำให้การทะเลาะวิวาทของพวกเขาหยุดลง</color>",
