  ui_story_5083_50830200_36_dialog_content = "Hup, two, three, four...",
  ui_story_5083_50830200_37_dialog_content = "<color=#e8d9bb>วิ่งไปเร็วขึ้นและเร็วขึ้น สามคนนั้นกำลังวิ่ง... ทั้งหมดของทหารกำลังมองพวกเขาอย่างใส่ใจ พวกเขาวิ่งหลายรอบในความเร็วที่ตรงไปที่เส้นชัย</color>",
