  ui_story_5083_50830200_65_dialog_content = "อะไรนะ!",
  ui_story_5083_50830200_66_dialog_content = "บาร์ตัน! ด็อก! คุณคนเกียจคร้านนี้คิดว่าคุณกำลังทำอะไรอยู่เหรอ?!",
  ui_story_5083_50830200_67_dialog_content = "เปลี่ยนเป็นยูนิฟอร์มของคุณและลากตูดที่น่าสงสารของคุณไปยังหอคอยกลาง! คุณจะยืนอยู่ใต้แสงของมันตลอดทั้งวัน ไม่มีข้อยกเว้น!!!",
  ui_story_5083_50830200_68_dialog_content = "ว-ว่าไงนะ?!?",
  ui_story_5083_50830200_69_dialog_content = "<color=#e8d9bb>หอคอยกลาง ศูนย์การขนส่งที่คึกคักและสว่างไสวนี้ทำหน้าที่เป็นหัวใจของเมืองแกนน่อน—</color>",
  ui_story_5083_50830200_70_dialog_content = "<color=#e8d9bb>นอกจากนี้ยังเป็นสถานที่ที่โดดเด่นสำหรับลงโทษทหารของอิลลูมินาที่ไม่ยอมปฏิบัติตามกฎ</color>",
  ui_story_5083_50830200_71_dialog_content = "...",
  ui_story_5083_50830200_72_dialog_content = "...",
  ui_story_5083_50830200_73_dialog_content = "... ขอโทษ.",
  ui_story_5083_50830200_74_dialog_content = "หา?",
  ui_story_5083_50830200_75_dialog_content = "ฉันคือเหตุผลที่คุณก็ได้รับ...",
  ui_story_5083_50830200_76_dialog_content = "คุณทำตัวแปลก ๆ มาหลายวันแล้วนะ บาร์ตัน",
  ui_story_5083_50830200_77_dialog_content = "เป็นเพราะการต่อสู้ครั้งนั้นหรือเปล่า?",
  ui_story_5083_50830200_78_dialog_content = "ฉันบอกเธอไว้แล้วว่าอย่าคิดมากเกินไป, ผู้ชาย. คุณไม่ได้ผิดหมดเลยในสิ่งนั้น.",
  ui_story_5083_50830200_79_dialog_content = "เรื่องก็ไม่ได้เป็นไปตามที่คุณต้องการเท่านั้นแหละ... ดังนั้นหยุดท้อแท้ไปแล้วนะ ไม่งั้นก็จะไม่รู้สึกดีเมื่อฉันทำให้คุณแพ้ในที่สุด",
  ui_story_5083_50830200_80_dialog_content = "ทั้งหมด... ผู้บัญชาการแพ็งโก้เคยพูดว่าคุณคือผู้ที่มีศักยภาพที่สุดในกลุ่มทหารใหม่ของเขา",
  ui_story_5083_50830200_81_dialog_content = "ฮะ? เขาจริง ๆ ชมฉันเหรอ?",
  ui_story_5083_50830200_82_dialog_content = "คุณจริงๆ คือคนงี่เง่าบางครั้ง—",
  ui_story_5083_50830200_83_dialog_content = "ขอบคุณนะ ด็อก",
  ui_story_5083_50830200_84_dialog_content = "?!",
  ui_story_5083_50830200_85_dialog_content = "ฉันเกือบลืมไปแล้ว แต่ฉันยังไม่ได้ขอบคุณคุณอย่างเหมาะสมสำหรับครั้งที่แล้วนะ",
  ui_story_5083_50830200_86_dialog_content = "ดังนั้นขอบคุณที่มาช่วยฉันทันเวลาจริง ๆ",
  ui_story_5083_50830200_87_dialog_content = "... ผมแค่ทำตามคำสั่งของผู้บัญชาการแพ็งโก้เท่านั้น ดังนั้นไม่ต้องพูดถึงมัน",
  ui_story_5083_50830200_88_dialog_content = "อื้อ... ร้อนมาก—",
  ui_story_5083_50830200_89_dialog_content = "<color=#e8d9bb>ภายใต้แสงที่ร้อนระอุของหอสูงกลาง, ทหารสองคนใช้เวลาทั้งวันในการเหงื่อออกและยืนเตรียมตัว.</color>",
  ui_story_5083_50830200_90_dialog_content = "<color=#e8d9bb>ณ สุดวันนั้น ผู้บังคับบัญชาที่ไร้ความเมตตาของพวกเขาปรากฏตัวขึ้นสุดท้ายและปลดพวกเขาออกจากการลงโทษ—</color>",
  ui_story_5083_50830200_91_dialog_content = "ในที่สุด... อีกไม่กี่นาทีแสงจากอิลลูมินาก็จะทำให้ฉันแห้งสนิทแล้ว",
  ui_story_5083_50830200_92_dialog_content = "ฉันประหลาดใจที่ด็อกยังมีพลังงานเพียงพอที่จะไปโรงอาหาร... คิดว่าฉันควรจะไปอาบน้ำก่อน...",
  ui_story_5083_50830200_93_dialog_content = "บี๊บ—บาร์ตันถูกพบ",
  ui_story_5083_50830200_94_dialog_content = "เอ๊ะ? มันเป็นโดรน... แล้วมันรู้ว่าฉันคือใครเหรอ?",
  ui_story_5083_50830200_95_dialog_content = "รอสักครู่, คุณคือโดรนของกรอนรูจากเช้าวันนี้หรือ?",
  ui_story_5083_50830200_96_dialog_content = "ไม่ บาร์ตัน... ฉันคือผู้นำทางของคุณ",
  ui_story_5083_50830200_97_dialog_content = "เอ๊ะ? มันหมายความว่ายังไง?",
  ui_story_5083_50830200_98_dialog_content = "ฉันอยู่ที่นี่เพื่อนำทางคุณ...",
  ui_story_5083_50830200_99_dialog_content = "มันก็ไม่ได้ช่วยให้เข้าใจมากขึ้นเท่าไหร่นะ... คุณรู้ไหมว่า ถึงแม้ว่าลักษณะของคุณจะดูเก่าๆ แต่ผมก็ยังคิดว่าคุณน่าสนใจอยู่นะ.",
  ui_story_5083_50830200_100_dialog_content = "... นี่หมายความว่าโดรนเป็นอุปกรณ์มาตรฐานแล้วหรือ?",
  ui_story_5083_50830200_101_dialog_content = "ฉันไม่รู้สึกว่ามันเป็นปัญหาเลย! ถ้าคุณมาที่นี่เพื่อนำทางให้ฉัน ก็ช่วยนำทางไปเลย!",
  ui_story_5083_50830200_102_dialog_content = "เข้าใจแล้ว",
  ui_story_5083_50830200_103_dialog_content = "บี๊ป—บาร์ตัน, ฉัน...",
  ui_story_5083_50830200_104_dialog_content = "ฉันจะนำทางคุณออกจากที่นี่...",
  ui_story_5083_50830301_1_dialog_content = "บี๊บ—บาร์ตัน... เซนเซอร์ของฉันบ่งบอกว่าคุณต้องการอาบน้ำ...",
  ui_story_5083_50830301_2_dialog_content = "ห้องอาบน้ำของหอพักกำลังเต็มอยู่ กำลังสแกนหาตัวเลือกทางเลือก... ฉันได้ค้นพบบ้านอาบน้ำสาธารณะในพื้นที่ที่อยู่อาศัย กำลังวางเส้นทาง... กรุณาตามฉันมา.",
  ui_story_5083_50830301_3_dialog_content = "เฮ้, ไม่เลวเลย! คุณฉลาดกว่าโมเดลอื่น ๆ ที่ฉันเคยเห็น!",
  ui_story_5083_50830301_4_dialog_content = "หรือฉันควรจะแกะนายออกมาดูว่ามีอะไรอยู่ข้างในรึเปล่า?",
  ui_story_5083_50830301_5_dialog_content = "บี๊บ—บี๊บ—โปรดอย่า—",
  ui_story_5083_50830301_6_dialog_content = "แค่ล้อเล่นเฉย ๆ นะเจ้าตัวเล็ก ถ้าฉันทำลายรุ่นที่ไม่เคยเห็นมาก่อนเช่นเธอ ฉันคงจะตกอยู่ในปัญหาที่ไม่สามารถบรรยายได้มากมาย",
  ui_story_5083_50830301_7_dialog_content = "บี๊ป—จุดหมายของเราอยู่ห่างออกไป 300 เมตร ที่สี่แยกถัดไป โปรดใช้ลิฟต์ขึ้นไปที่ชั้นสอง",
  ui_story_5083_50830301_8_dialog_content = "คุณน่ารักจริงๆนะ น้องเล็ก! เมือง Gannon บางครั้งมันยากที่จะเดินทางได้เลย",
  ui_story_5083_50830301_9_dialog_content = "ฉันแค่หวังว่าเราจะสามารถใช้คุณใน Undercities อื่น ๆ ได้!",
  ui_story_5083_50830301_10_dialog_content = "ตำแหน่งปัจจุบัน: ภูมิภาคที่อยู่อาศัย, ซอย 9, ชั้นบน... ตำแหน่งที่จะถึง: อนุสาวรีย์กลาง—",
  ui_story_5083_50830301_11_dialog_content = "รอก่อน",
  ui_story_5083_50830301_12_dialog_content = "บี๊บ—ใช่ คุณบาร์ตัน...?",
  ui_story_5083_50830301_13_dialog_content = "ที่ระลึกนั้น...",
  ui_story_5083_50830301_14_dialog_content = "แม้จากที่นี่ ฉันยังสามารถเห็นมันได้ชัดเจน",
  ui_story_5083_50830301_15_dialog_content = "ฉันสงสัย... หากชื่อพวกเขาถูกเพิ่มเข้าไปแล้วหรือยัง?",
  ui_story_5083_50830301_16_dialog_content = "<color=#e8d9bb>การต่อสู้ที่เกิดขึ้นไม่นานมานี้ เป็นครั้งแรกที่บาร์ตันได้สัมผัสการสู้รบจริง</color>",
  ui_story_5083_50830301_17_dialog_content = "<color=#e8d9bb>วันนั้นมืดมิดและมีเมฆครึ้มปกคลุม ฝนตกลงมาจากท้องฟ้าเหมือนเส้นใยนับไม่ถ้วนที่ไม่มีที่สิ้นสุด</color>",
  ui_story_5083_50830301_18_dialog_content = "เร็วๆนี้! ย้ายกระสอบทรายไปยังแนวหน้าสุดของเรา!",
  ui_story_5083_50830301_19_dialog_content = "ร่องที่สองทางขวาของเราถูกอิคลิพไซท์ท่วมท้น! ส่งทหารไปขจัดทันที!",
  ui_story_5083_50830301_20_dialog_content = "เราไม่มีกระสอบทรายเพียงพอนายหญิง!",
  ui_story_5083_50830301_21_dialog_content = "หรือทหารของเรา... เราไม่สามารถรักษาตำแหน่งทั้งหมดของเราได้แล้ว",
  ui_story_5083_50830301_22_dialog_content = "ชาวเมืองอพยพเสร็จหรือยังคะ?",
  ui_story_5083_50830301_23_dialog_content = "ไม่ครับ นายหญิง... ความเสียหายที่แกนพลังงานของ Undercity ทำให้ระบบขนส่งส่วนใหญ่ของเราล็อคอยู่ ทำให้การอพยพช้าลงมาก",
  ui_story_5083_50830301_24_dialog_content = "ตอนนี้เราควรทำยังไงดี",
  ui_story_5083_50830301_25_dialog_content = "ค้นหาอะไรก็ตามที่คุณสามารถใช้เพื่อเสริมแนวป้องกันแนวหน้าของเรา และแบ่งงานที่เหลือให้กับกำลังทหารที่เหลืออยู่ของเรา ไม่มีทางเลือกอื่นแล้ว",
  ui_story_5083_50830301_26_dialog_content = "ร้อยโทบาร์ตันอยู่ที่ไหน? ฉันไม่สามารถตัดสินใจทุกอย่างที่นี่ได้ ดังนั้นฉันจะให้เขาประเมินสถานการณ์",
  ui_story_5083_50830301_27_dialog_content = "เขาเพิ่งกลับมาจากแนวหน้า และกำลังพักผ่อนอยู่ที่แถวหลัง",
  ui_story_5083_50830301_28_dialog_content = "หน่วยสอดแนม! ยังมีเวลานานแค่ไหนกว่าสัตว์ประหลาดจะเริ่มโจมตีอีกครั้ง?",
  ui_story_5083_50830301_29_dialog_content = "ไม่นานแล้ว นายหญิง! พวกมันกำลังเติมเต็มกำลังขณะนี้เลย!",
  ui_story_5083_50830301_30_dialog_content = "เจ้าหน้าที่สื่อสารอยู่ที่ไหน? เราซ่อมถนนเสร็จแล้วหรือยัง? ผู้บัญชาการแพ็งโก้และทหารของเขาจะมาถึงในเวลาเท่าไหร่?!",
  ui_story_5083_50830301_31_dialog_content = "ขอโทษนะคะ นายหญิง แต่ทีมสื่อสารทั้งหมดได้หายไปแล้วค่ะ",
  ui_story_5083_50830301_32_dialog_content = "โปรดสั่งการด้วย นายหญิง?",
  ui_story_5083_50830301_33_dialog_content = "ผู้บัญชาการแพ็งโก้และกองทัพของเขาจะมาแน่นอน เราต้องต้านทานไว้จนกว่าเขาจะมาถึง",
  ui_story_5083_50830301_34_dialog_content = "หกเมืองใต้ดินของเรากำลังถูกโจมตีอยู่ในตอนนี้ และมีคนที่ต้องการการส่งกำลังเสริมมากกว่าเราอยู่ที่นี่",
  ui_story_5083_50830301_35_dialog_content = "ถ้าผู้บัญชาการถูกกั้นอยู่ที่แนวหน้า...",
  ui_story_5083_50830301_36_dialog_content = "แล้วเราก็ต้องทนอยู่เพื่อคนพวกนั้นด้วย",
  ui_story_5083_50830301_37_dialog_content = "เราจะ... ฉันยังมีครอบครัวที่บ้าน...",
  ui_story_5083_50830301_38_dialog_content = "ฉันขอโทษ... แต่ฉันไม่สามารถสัญญาอะไรกับคุณในตอนนี้",
  ui_story_5083_50830301_39_dialog_content = "หน้าที่ของเราคือการปกป้องที่นี่ด้วยชีวิตของเรา เราไม่สามารถยอมให้อิคลิพไซท์ผ่านไปได้",
  ui_story_5083_50830301_40_dialog_content = "สหายชาวอิลลูมินาของเรากำลังพึ่งพาเราในการปกป้องพวกเขา...",
  ui_story_5083_50830301_41_dialog_content = "ถ้าต้องตาย เราจะตายอย่างมีเกียรติบนสนามรบ",
  ui_story_5083_50830301_42_dialog_content = "ฉันกลัว... แม่ฉันให้ผ้าพันคอใหม่ก่อนที่ฉันจะออกไป แต่ตอนนี้... ฉันแม้แต่ไม่รู้ว่ามันเมื่อไหร่ที่ถูกเผาไหม้อย่างนี้...",
  ui_story_5083_50830301_43_dialog_content = "...",
  ui_story_5083_50830301_44_dialog_content = "... ฉันรู้ว่าการที่ฉันทำแบบนี้ไม่ถูกต้อง แต่ให้มีคนไปปลุกร้อยโทบาร์ตันขึ้นทันที",
  ui_story_5083_50830301_45_dialog_content = "อาจจะเป็นเขาที่รู้ว่าต้องทำอย่างไร",
  ui_story_5083_50830301_46_dialog_content = "ร้อยโทบาร์ตัน—ร้อยโท—",
  ui_story_5083_50830301_47_dialog_content = "มันคืออะไรนะ? รู้สึกเหมือนฉันเพิ่งหลับไป... แต่ไม่เป็นไร คุณก็พักผ่อนสักหน่อยสิ; ไม่มีใครรู้ว่าพวกเขาจะโจมตีอีกเมื่อไหร่",
  ui_story_5083_50830301_48_dialog_content = "ท่าน! กองทหารสื่อสารของเราถูกกำจัดไปแล้ว และเราไม่มีวิธีการติดต่อกับกองทัพที่เหลือ",
  ui_story_5083_50830301_49_dialog_content = "ผู้บัญชาการกองพันและเจ้าหน้าที่วินัย... ก็ถูกสูญเสียไปในการป้องกันการถอยกลับครั้งล่าสุดของเราด้วย.",
  ui_story_5083_50830301_50_dialog_content = "เข้าใจแล้ว... ตามลำดับขั้นความคำสั่ง ผมควรจะเป็นผู้ควบคุมที่นี่ตอนนี้ ใช่ไหม?",
  ui_story_5083_50830301_51_dialog_content = "ให้ฉันแผนที่สิ",
  ui_story_5083_50830301_52_dialog_content = "หน่วยสอดแนมรายงานว่าอิคลิพไซท์กำลังรวมตัวที่พื้นที่สูงทางทิศเหนือ เราไม่มีทางจะโจมตีพวกมันจากระยะไกลในตอนนี้",
  ui_story_5083_50830301_53_dialog_content = "ฟังก์ชันส่วนใหญ่ของ Undercity ถูกปิดใช้งานหลังจากคลื่นแรกของการโจมตี",
  ui_story_5083_50830301_54_dialog_content = "ณ จุดนี้ เราไม่มีทางทราบว่าผู้บัญชาการจะมาพร้อมกับกำลังเสริมหรือไม่ หรือจะมาเมื่อไหร่",
  ui_story_5083_50830301_55_dialog_content = "แล้วก็... บางทหารเชื่อว่าเราควรถอนตัวจากที่นี่และอพยพไปพร้อมกับพลเมือง",
  ui_story_5083_50830301_56_dialog_content = "แต่นั่นหมายความว่าเราจะต้องทิ้งเมืองใต้ดินทั้งเมืองไปเลยครับ!",
  ui_story_5083_50830301_57_dialog_content = "เรายังมีคนเหลืออีกเท่าไหร่?",
  ui_story_5083_50830301_58_dialog_content = "น้อยกว่าสามร้อย... เราไม่มีจำนวนที่เพียงพอในการป้องกันเมืองใต้ดินนี้อีกต่อไป",
  ui_story_5083_50830301_59_dialog_content = "... นี่ยากกว่าการจำลองทางทหารใด ๆ แน่นอนนั่นเอง.",
  ui_story_5083_50830301_60_dialog_content = "ฉันไม่สามารถเชื่อได้ว่าคนแก่คนนั้นคิดว่าเราจะสามารถป้องกันเมืองทั้งหมดด้วยตัวเราเอง... ถ้าเราไม่ได้เสี่ยงชีวิตเพื่อที่จะทะยานออกมา เราอาจจะตายที่นั่นแล้ว",
  ui_story_5083_50830301_61_dialog_content = "ดูเหมือนว่าเราก็ยังมีทางเดียวที่เหลืออยู่...",
  ui_story_5083_50830301_62_dialog_content = "ร้อยโทบาร์ตัน! <size=45>มีผู้ส่งข้อความมาถึง!</size>",
