  ui_story_5083_50830301_73_dialog_content = "I'm sorry?",
  ui_story_5083_50830301_74_dialog_content = "ในฐานะผู้บัญชาการ ฉันสั่งให้ทหารทั้งหมดเตรียมพร้อมที่จะพุ่งเข้าสู่ศัตรู!",
