  ui_story_5083_50830400_59_dialog_content = "เมื่อพูดถึงการวิจัย... ฉันคิดว่ามันก็สนุกดีนะ",
  ui_story_5083_50830400_60_dialog_content = "เห็นไหม? และฉันสามารถบอกได้ว่าคุณก็สนใจในเกมเหล่านี้เหมือนกัน บาร์ตัน คิดว่าครั้งนี้คุณจะปล่อยฉันได้ไหม?",
  ui_story_5083_50830400_61_dialog_content = "อืมม, ฉันชอบเล่นกับอุปกรณ์ใหม่ ๆ เหมือนคนอื่น ๆ บอกเลย, คืนคูปองให้ฉัน แล้วฉันจะทำเป็นว่าเรื่องนี้ไม่เคยเกิดขึ้น",
  ui_story_5083_50830400_62_dialog_content = "โอ้ อย่าทำแบบนั้นสิ! มีอะไรผิดกับการเวทนาร้านของเราหน่อยหรือ?",
  ui_story_5083_50830400_63_dialog_content = "สุดท้ายแล้ว ทุกชิ้นของเทคโนโลยีใหม่ที่ฉันพัฒนาขึ้นมานั้น ถูกออกแบบมาเพื่อช่วยเหลือทหารสู้หน้าแนวอย่างคุณ",
  ui_story_5083_50830400_64_dialog_content = "ช่วยด้วยหรือ... เดี๋ยวนี่ นึกภาพนึกถึง! คุณรู้จักโดรนตัวนี้มั้ย?",
  ui_story_5083_50830400_65_dialog_content = "ฮะ? มันหายไปไหน?",
  ui_story_5083_50830400_66_dialog_content = "โดรนคืออะไร?",
  ui_story_5083_50830400_67_dialog_content = "มันคือโดรนที่ดูเก่าเกินไปที่มาหาฉันเช้านี้ มันเรียกตัวเองว่าเป็นนาวิเกเตอร์ของฉัน!",
  ui_story_5083_50830400_68_dialog_content = "ฉันตามไปคุยกับมันทั้งวันเลย",
  ui_story_5083_50830400_69_dialog_content = "ว้าว ฟังดูเป็นเทคโนโลยีล้ำสมัยนะ ใช่มั้ยเนี่ย ดีเนียร์?",
  ui_story_5083_50830400_70_dialog_content = "เห็นด้วย ฉันไม่คิดว่าอิลลูมินามีเทคโนโลยีอัจฉริยะประเภทนั้นแล้ว และสำหรับคุณที่พูดว่ามัน \"ดูเก่า\" ยิ่งทำให้ไม่มีเหตุผลเลย...",
  ui_story_5083_50830400_71_dialog_content = "จริงเหรอ? เพราะฉันคิดว่าคุณทำมันเองนะ ไม่รู้ว่าเจ้าตัวน้อยนั้นไปไหน... แต่ฉันแน่ใจว่ามันไม่ได้หลงทาง เพราะมันเป็นโดรนนำทางอยู่แล้วสินะ.",
  ui_story_5083_50830400_72_dialog_content = "คราวหน้าที่ฉันมีโอกาส ฉันจะแสดงให้คุณดูนะ",
  ui_story_5083_50830400_73_dialog_content = "ฉันอยากจะลองมาดูด้วย... อะไรก็ตามที่นำไปสู่อนาคตที่แข็งแกร่งขึ้น จะเสมอทำให้ฉันสนใจ",
  ui_story_5083_50830400_74_dialog_content = "นี่คือบัตรคูปองของคุณ บาร์ตัน อย่าลืมที่จะเก็บสถานที่นี้เป็นความลับเล็ก ๆ ระหว่างเรานะ โอเค?",
  ui_story_5083_50830400_75_dialog_content = "เอาล่ะ และขอบคุณนะ! ฉันหาครั้งที่จะได้มาที่นี่ไม่ได้บ่อย ดังนั้นฉันยังไม่อยากกลับเลย ว่าแต่ฉันจะพาคุณทั้งสองไปทานอาหารที่ดี ๆ ได้ไหม?",
  ui_story_5083_50830400_76_dialog_content = "นับฉันด้วยนะ! ฉันรู้อยู่แล้วว่าคุณบาร์ตันคือคนดี!",
  ui_story_5083_50830400_77_dialog_content = "ฉันก็ได้ลิ้มรสอาหารในห้องปฏิบัติการเต็มที่แล้ว ขอบคุณนะ... และถ้ามันดีจริง ๆ ฉันอยากจะแนะนำให้พี่สาวของฉันลองดู",
  ui_story_5083_50830400_78_dialog_content = "โอ้ ใช่เลย! เฮ้ บาร์ตัน คุณรู้ไหมว่าพี่สาวของเธอคือไม่ใช่ใครอื่นแต่ไรน์ฮาร์ตที่ยิ่งใหญ่นั่นเอง?",
  ui_story_5083_50830400_79_dialog_content = "อย่าพูดแบบนั้นนะ กรอนรู มันทำให้เขินนะ",
  ui_story_5083_50830400_80_dialog_content = "จริงเหรอ? ฉันแยกไม่ออกเลย เพราะน้องสาวของคุณเปล่งประกายสว่างกว่าใครทั้งหมด",
  ui_story_5083_50830400_81_dialog_content = "... ฉันจะไล่ตามเธอได้สักวันหนึ่ง",
  ui_story_5083_50830400_82_dialog_content = "จริงหรือ? เพราะฉันคิดว่าคุณทำได้ดีแล้วนะ—ตอนนี้ไปทานข้าวกันเถอะ!",
  ui_story_5083_50830400_83_dialog_content = "ไม่เลวเลยนะ ผมว่าผมสามารถแนะนำให้... เธอได้นะ",
  ui_story_5083_50830400_84_dialog_content = "ฮืม... คุณสองคนนี่จริง ๆ แล้วต่างกันมากเลยนะ",
  ui_story_5083_50830400_85_dialog_content = "ฉันรู้ว่าคุณได้เห็นไรน์ฮาร์ตทำงานแล้ว แต่คุณยังไม่มีโอกาสได้เห็นดีเนียร์ส่องสว่าง บาร์ตัน",
  ui_story_5083_50830400_86_dialog_content = "คุณชอบการรบจำลองทางทหารใช่ไหม? อาจจะเล่นแข่งกันสองคนได้นะ",
  ui_story_5083_50830400_87_dialog_content = "ฉันยินดีกับการแข่งขันอื่นๆ แต่การทดสอบกลยุทธ์การต่อสู้ต่อหน้ากับนักวิจัย? แน่นอน มาสิ!",
  ui_story_5083_50830400_88_dialog_content = "ฉันไม่ได้ขอให้คุณมาเป็นปัญหาให้ฉัน กรอนรู... แต่ก็ดี ฉันยอมรับคำท้าของคุณ ร้อยโทบาร์ตัน แต่ฉันขอเตือนคุณก่อน: ถ้าฉันเป็นคุณ ฉันคงจะไม่ได้ดูถูกฉันเลย",
  ui_story_5083_50830400_89_dialog_content = "<color=#e8d9bb>กลุ่มนี้กลับไปที่ร้านค้าที่กรอนรูซ่อนไว้ ที่บาร์ตันและดีเนียร์มีการสู้กันจำลองบนโต๊ะทราย.</color>",
  ui_story_5083_50830400_90_dialog_content = "<color=#e8d9bb>เพื่อความประหลาดใจของบาร์ตัน กลยุทธ์ของดีเนียร์กล้าหาญและไม่ยั้งยืนยันมากกว่าที่เขาคาดหวังจากนักวิจัย</color>",
  ui_story_5083_50830400_91_dialog_content = "<color=#e8d9bb>โดยการสละเบี้ยต่อเบี้ย เธอกดดันเข้าไปในพื้นที่ของบาร์ตันอย่างลึกซึ้ง ซึ่งทำให้เขาตกใจ ในเวลาที่เขาตระหนักถึงความเสี่ยงของสถานการณ์ของเขา เขาก็อยู่ในช่วงเวลาที่จะพ่ายแพ้แล้ว</color>",
  ui_story_5083_50830400_92_dialog_content = "(ไม่ดีแล้ว! ฉันเพิ่งแพ้กรอนรูไป ฉันไม่สามารถแพ้เพื่อนของเธอได้อีก!)",
  ui_story_5083_50830400_93_dialog_content = "<color=#e8d9bb>บาร์ตันเผยอแผ่อายและทันทีทุบตัวถัดไปลงไปในตำแหน่ง ทำให้ด้านของดีเนียร์บนกระดานเกมเสียหาย</color>",
  ui_story_5083_50830400_94_dialog_content = "<color=#e8d9bb>ขณะที่เธอรีบเร่งจัดเรียงหมากของเธอใหม่ บาร์ตันกดดันด้วยเหตุผลของเขาและเริ่มต้นการโจมตีอย่างต่อเนื่อง</color>",
  ui_story_5083_50830400_95_dialog_content = "นั่นเป็นการเล่นที่ไม่สุจริตนะ บาร์ตัน... ดูสิ? ดีเนียร์กำลังจะร้องไห้...",
  ui_story_5083_50830400_96_dialog_content = "คุณธรรมไม่มีความหมายในสนามรบ; สิ่งที่สำคัญคือการชนะและแพ้! ผู้บัญชาการของฉันสอนฉันที่จะชนะไม่ว่าจะต้องเสียอะไร และนั่นเองคือสิ่งที่ฉันจะทำ!",
  ui_story_5083_50830400_97_dialog_content = "<color=#e8d9bb>แม้ว่าคำพูดของเขาจะรุนแรง แต่ระยะห่างก็ยังคงยากที่จะลดลง หลังจากวางหมากลงบนกระดานทราย ดีเนียร์ก็เริ่มที่จะสามารถควบคุมอารมณ์ของตนได้อีกครั้ง</color>",
  ui_story_5083_50830400_98_dialog_content = "<color=#e8d9bb>การดึงดูด, การโจมตีด้านข้าง, และการทำลายศัตรูโดยการสละเบี้ยของเธออย่างต่อเนื่อง... นั่นคือวิธีที่ดีเนียร์ชนะในการต่อสู้ของพวกเขา</color>",
  ui_story_5083_50830400_99_dialog_content = "ฮ่าฮ่าฮ่า! ดูเหมือนว่าเธอจะชนะคุณทั้งในเรื่องกลยุทธ์และมารยาทเลยนะ บาร์ตัน!",
  ui_story_5083_50830400_100_dialog_content = "คุณเรียกตัวเองว่าร้อยโทด้วยการใช้กลยุทธ์ที่ไม่ซื่อสัตย์เหรอ? รอดูเถอะ จนกว่าฉันจะบอก...",
  ui_story_5083_50830400_101_dialog_content = "เออ... ร-รอสักครู่ คุณทั้งสอง! คุณไม่สามารถบอกใครเกี่ยวกับสิ่งที่เกิดขึ้นที่นี่วันนี้! ขอร้องนะ!",
  ui_story_5083_50830400_102_dialog_content = "ถ้าข่าวนี้หลุดออกไป ฉันจะไม่มีวันลืมเลย! <size=45>ขอร้อง! ฉันจะทำอะไรก็ได้!!!</size>",
  ui_story_5083_50830500_1_dialog_content = "<color=#e8d9bb>บาร์ตันที่มีหน้าที่หม่นหมองกลับมาที่ประตูค่ายโดยถือถุงหลายขนาดมาด้วย ฉันต้องไปเตือนเขา—</color>",
  ui_story_5083_50830500_2_dialog_content = "คุณไปที่ไหนมา? คุณหายไปครึ่งวันนะครับ...",
