  ui_story_5083_50830500_5_dialog_content = "<color=#e8d9bb>ไรน์ฮาร์ตยืนอยู่ที่ศูนย์กลางของสนามฝึกของกองพลที่ 2 ด้วยหอกอยู่ในมือ เธอดูเหมือนจะรอมานานแล้ว</color>",
  ui_story_5083_50830500_6_dialog_content = "เธอดูเหมือนว่าพร้อมที่จะฆ่าใครสักคน ไม่รู้ว่าใครทำให้เธอโกรธนะ?",
  ui_story_5083_50830500_7_dialog_content = "...",
  ui_story_5083_50830500_8_dialog_content = "<size=45>บาร์ตัน—!</size>",
