  ui_story_5083_50830500_14_dialog_content = "<color=#e8d9bb>ไรน์ฮาร์ตไล่ตามบาร์ตันอย่างไร้ความปรานี ด้วยหอกที่ลุกไหม้ของเธอที่ตัดทะลุความมืดของคืนอยู่ตลอดเวลา</color>",
