  ui_story_5083_50830500_23_dialog_content = "<color=#e8d9bb>ทั้งสองคนต่อสู้กันไปมาตามถนน ทำให้เกิดความตื่นตระหนกไม่น้อย ทหารรีบมาที่เกิดเหตุ แต่ยังไม่แน่ใจว่าจะแยกการทะเลาะวิวาทอย่างรุนแรงนี้อย่างไร</color>",
