  ui_story_5083_50830500_26_dialog_content = "ฮ่าฮ่า, ไม่เลวนะ! ติดตามต่อไป!",
  ui_story_5083_50830500_27_dialog_content = "<size=45>เคาะมันออก, คุณพวกตัวตลก!</size>",
