  ui_story_5083_50830600_34_dialog_content = "นายมาทำอะไรที่นี่",
  ui_story_5083_50830600_35_dialog_content = "ฉันกำลังศึกษาประวัติศาสตร์ แน่นอน ประวัติศาสตร์ของอิลลูมินา, ประวัติศาสตร์ของสงคราม, สิ่งที่เช่นนั้น.",
  ui_story_5083_50830600_36_dialog_content = "...คุณคิดว่าอิลลูมินาในอนาคตจะเป็นอย่างไร บาร์ตัน?",
  ui_story_5083_50830600_37_dialog_content = "จะถามทำไม",
  ui_story_5083_50830600_38_dialog_content = "เคเลสไทต์ที่ลึกลับถูกกำจัดไปด้วยการโจมตีที่ไม่คาดคิดเพียงครั้งเดียว ด้วยเหตุนี้ พวกเราออโรเรียนจะไม่มีโอกาสได้รับคำแนะนำจากพวกเขาอีกเลย",
  ui_story_5083_50830600_39_dialog_content = "<color=#FFB400>วิกฤตดาร์กโอเวอร์</color>ยังไม่จบสิ้น และเราก็ยังคงสูญเสียทหารเพิ่มขึ้นเรื่อย ๆ ดูออกไปทางหน้าต่าง—คุณสามารถเห็นอนุสรณ์สถานของผู้ที่ตกสู้จากที่นี่ได้รึเปล่า?",
  ui_story_5083_50830600_40_dialog_content = "ชื่อของพี่ชายและพี่สาวทุกคนที่เราสูญเสียไปในสงครามถูกสลักลงไปที่นั่น... แต่ฉันยังได้ยินเสียงของพวกเขาก้องก echoing ในหัวของฉัน",
  ui_story_5083_50830600_41_dialog_content = "ทุกคนเราเริ่มเรียนรู้ประวัติศาสตร์ตั้งแต่ยังเด็ก... และยิ่งฉันอายุมากขึ้น ฉันรู้สึกใกล้ชิดกับสิ่งที่ถูกอนุรักษ์ที่นี่มากขึ้น",
  ui_story_5083_50830600_42_dialog_content = "หลังจากดูเพื่อนๆของฉันสละชีวิตในสนามรบ เพียงเพื่อให้การสละสิ้นเป็นบทเรียนประวัติศาสตร์สำหรับรุ่นหลัง... ฉันเริ่มรู้สึกสับสน บาร์ตัน",
  ui_story_5083_50830600_43_dialog_content = "สับสนหรือ?",
  ui_story_5083_50830600_44_dialog_content = "แอสตราอยู่ในอันตรายมหันต์ และแม้ว่าฉันยินดีที่จะสละชีวิตเพื่อเขา ฉันก็ยังมองไม่เห็นอนาคตของมัน...",
  ui_story_5083_50830600_45_dialog_content = "คุณรู้ไหมว่าคนในลูโมโพลิสกำลังต่อสู้กันอยู่ในตอนนี้ ใช่ไหม? คำสัญญาที่จะช่วยเราของพวกเขาไม่เคยเป็นจริง และเราก็หยุดการแลกเปลี่ยนทรัพยากรกับพวกเขาไปแล้ว",
  ui_story_5083_50830600_46_dialog_content = "ทั้งหมดของแอสตรากำลังอยู่ในสภาวะที่ยุ่งเหยิงในตอนนี้ ฉันไม่แน่ใจว่าฉันกำลังสู้เพื่ออะไรอีกต่อไป หรือว่าเราสามารถชนะได้หรือไม่",
  ui_story_5083_50830600_47_dialog_content = "... คุณกลัวเหรอ?",
  ui_story_5083_50830600_48_dialog_content = "แน่นอนว่าฉันกลัว... โชคคือเหตุผลเดียวที่เรารอดชีวิต เมื่อเพื่อนร่วมทัพของเราคนอื่น ๆ ไม่ได้รอด",
  ui_story_5083_50830600_49_dialog_content = "คุณบอกฉันว่าสิ่งนี้เราต้องทนตลอดชีวิต ฉันกำลังทำอย่างที่สุดเพื่อใช้ชีวิตอยู่กับมัน...",
  ui_story_5083_50830600_50_dialog_content = "คุณรู้ไหมว่าคณะกรรมาธิการได้มีการแทรกแซงในแผนของท่านจอมทัพ? พวกเขายังไม่สามารถตัดสินใจเรื่องวิธีการที่ดีที่สุดในการดำเนินสงคราม น่าปลอบใจจริงๆ ใช่ไหม?",
  ui_story_5083_50830600_51_dialog_content = "อย่างไรก็ตาม ฉันเดิมพันว่าความกลัวของฉันนั้นไม่เทียบได้กับทหารที่กลับมาจากสงครามเขตแดนมืด",
  ui_story_5083_50830600_52_dialog_content = "ตามที่เป็นอยู่ อิลลูมินาไม่มีกัปตันที่ชัดเจนอยู่ที่หัวเรือ มันไม่ทำให้คุณกลัวหรือไม่ บาร์ตัน?",
