  ui_story_5083_50830600_55_dialog_content = "เรามีสิทธิ์ในการแสดงความคิดเห็นในเรื่องต่าง ๆ ใช่ไหม?",
  ui_story_5083_50830600_56_dialog_content = "สุดท้ายแล้ว นี่คืออนาคตที่เรากำลังพูดถึง! มีใครจะเหมาะสมกับการต้อนรับความท้าทายในอนาคตมากกว่าผู้นำรุ่นใหม่หรือไม่?",
  ui_story_5083_50830600_57_dialog_content = "ไม่ว่าใครจะคิดอย่างไร ฉันจะไม่ยอมถอยหลัง ฉันจะไม่ปล่อยให้อิลลูมินาล่มลงเพียงเพราะไม่มีใครรู้วิธีควบคุมมัน!",
