  ui_story_5083_50830600_72_dialog_content = "เขาคือผู้บัญชาการของเรา และเขาได้ฝึกฝนเราให้เต็มที่ที่เขาสามารถทำได้ นั่นไม่ใช่เหตุผลที่เพียงพอหรือ?",
  ui_story_5083_50830600_73_dialog_content = "มันก็ใช่ แต่ฉันแน่ใจว่านั่นไม่ใช่เหตุผลเดียว",
