  ui_story_5083_50830801_2_dialog_content = "<color=#e8d9bb>หลังจากถูกล้อมรุมมาหลายวัน ปืนระยะสั้นทั้งหมดของเมืองไม่ว่าจะหมดกระสุนหรือถูกทำลายอย่างสมบูรณ์ ประชาชนที่อยู่ภายในสามารถทำได้แค่รอคอยจนกว่าจะสิ้นสุดในความเงียบที่ไม่มีทางออก</color>",
  ui_story_5083_50830801_3_dialog_content = "<color=#e8d9bb>ที่ทางเข้าเดียวของเมืองใต้ดิน ทหารของอิลลูมินาต่อสู้อย่างหนักเพื่อป้องกันอิคลิพไซท์ไม่ให้เข้ามา ไม่มีกระสุน พวกเขาใช้ดาบของตน; ไม่มีดาบ พวกเขาใช้กำปั้นของตน</color>",
  ui_story_5083_50830801_4_dialog_content = "<color=#e8d9bb>ยึดมั่นในความเชื่อว่าพวกเขาคือโล่ป้องกันของสหพันธ์ พวกเขาต่อสู้โดยไม่มีความคิดอื่นใดในใจนอกจากแสงสว่างแห่งความหวังที่แสนบางเบา</color>",
  ui_story_5083_50830801_5_dialog_content = "<color=#e8d9bb>\"ผู้ส่งข้อความได้หลุดออกมาแล้ว เมืองแกนน่อนจะส่งกำลังเสริมมาในไม่ช้า\"</color>",
  ui_story_5083_50830801_6_dialog_content = "<color=#e8d9bb>หลังจากสิบวัน แสงสว่างอันริบหรี่นั้นเริ่มมีความลัวลือ แต่ก่อนที่มันจะถูกดับสิ้น เหล่าทหารที่มั่นคงได้เห็นคำตอบที่พวกเขาได้ละหมาดไว้ อยู่เลยทางทะเลของเลือดและกระดูก—</color>",
  ui_story_5083_50830801_7_dialog_content = "<size=45>ส่งพวกมันไปปลิว!</size>",
  ui_story_5083_50830801_8_dialog_content = "นั่นคือโอกาสของเรา! ส่งนักสู้ของเราไปเสริมแรงที่ตำแหน่งนั้น!",
  ui_story_5083_50830801_9_dialog_content = "เติมกระสุนให้ทุกคนก่อนที่จะตรวจสอบการป้องกันของเมือง! ใช้ปืนใหญ่ระยะสั้นที่ยังคงทำงานอยู่ และนำส่วนที่เหลือมาใช้เป็นปืนใหญ่ที่ใช้ได้เพียงครั้งเดียว!",
  ui_story_5083_50830801_10_dialog_content = "ไรน์ฮาร์ต! ไปตรวจสอบสถานะของเมืองในขณะที่เรายืนยันที่ทางเข้า!",
  ui_story_5083_50830801_11_dialog_content = "โคโลญ! นำรถบรรทุกเกราะนั้นมาที่นี่!",
  ui_story_5083_50830801_12_dialog_content = "ฉันมากับกองกำลังสำรองที่ถูกส่งมาจากเมืองแกนน่อน! ใครคือผู้ควบคุมเมืองนี้ในตอนนี้?",
  ui_story_5083_50830801_13_dialog_content = "ผู้บัญชาการของเราเสียชีวิตในสนามรบ—คุณสามารถส่งข้อมูลใดๆ มาให้ฉันได้!",
  ui_story_5083_50830801_14_dialog_content = "แผนกทหารเรือรบกลจะทำให้สถานการณ์บนพื้นผิวเสถียร พาทหารที่เหลือของคุณไปเริ่มต้นการป้องกันและกั้น!",
  ui_story_5083_50830801_15_dialog_content = "เรื่องของพลเมือนที่ยังถูกกักตัวอยู่ที่นี่ โหลดทรัพยากรที่มีค่าลงในยานพาหนะเกราะของเราแล้วใช้มันอพยพทันที—",
  ui_story_5083_50830801_16_dialog_content = "แต่คุณและทหารของคุณล่ะ?",
