  ui_story_5083_50830801_61_dialog_content = "ฉันบอกคุณไปแล้ว ฉันชื่อวราธ—จอมทัพของอิลลูมินาในอนาคต! ฉันจะไม่ให้ใครหยุดฉันจากการปฏิบัติตามความยุติธรรมของฉัน!",
  ui_story_5083_50830801_62_dialog_content = "<color=#e8d9bb>วราธนำการโจมตีต่อต้านอิคลิพไซท์ที่พุ่งตัวขึ้นบันได ดาบที่เต้นไปมาของเธอตัดทางผ่านกองทหารของพวกเขาเป็นทางเลือด Eventually, she reaches the bottom floor of the Undercity.</color>",
  ui_story_5083_50830801_63_dialog_content = "คุณทั้งหมดเห็นมั้ย? ทหารนั้นคืออนาคตของอิลลูมินา...ผลลัพธ์ของความอุทิศสุดท้ายและการฝึกฝนของเรา...",
  ui_story_5083_50830801_64_dialog_content = "เธอคือ \"ฟอสเฟรัส\" ที่เราทั้งหมดฝันถึง... แสงของเธอ... มันสว่างสดใสอย่างแท้จริง...",
  ui_story_5083_50830801_65_dialog_content = "ความฝันของเรากำลังส่องสว่างอยู่หน้าเราในตอนนี้... เราจะยอมให้มันดับไปได้อย่างไร?",
  ui_story_5083_50830801_66_dialog_content = "... ฉันจะทำให้แน่ใจว่าเส้นทางอพยพของที่หลบภัยจะถูกเคลียร์ภายในสิบนาทีถัดไป แม้ว่ามันจะเสียชีวิตฉันก็ตาม",
  ui_story_5083_50830801_67_dialog_content = "และฉันจะนำทีมไปพบกับเธอ ส่วนที่เหลือขึ้นอยู่กับคุณ",
  ui_story_5083_50830801_68_dialog_content = "<color=#FFB400>แสงแห่งฟอสเฟรัส</color>... ไม่ว่าจะเกิดอะไรขึ้น ฉันต้องให้ทุกคนเห็นมัน—",
  ui_story_5083_50830801_69_dialog_content = "<color=#e8d9bb>ที่ชายเขตของ Undercity, ไฟของสงครามไหม้ไปอย่างรุนแรงต่อเนื่องสามวันโดยไม่มีสัญญาณของการส่งกำลังเสริม</color>",
  ui_story_5083_50830801_70_dialog_content = "<color=#e8d9bb>เมื่อทุกอย่างในคลังกระสุนหมดอีกครั้ง ทหารจึงต้องกลับไปสู้รบในระยะประชิดอีกครั้ง</color>",
  ui_story_5083_50830801_71_dialog_content = "ถือสาย! เราต้องรักษาตำแหน่งนี้ ไม่งั้นพวกมันจะปิดทางเข้า!",
  ui_story_5083_50830801_72_dialog_content = "คำราม—!",
  ui_story_5083_50830801_73_dialog_content = "ไม่ได้อยู่ในนาฬิกาของฉัน!",
  ui_story_5083_50830801_74_dialog_content = "Heh, ชายชรา... ฉันหมายถึง ผู้บัญชาการแพ็งโก้นั่นแหละ! มันถูกต้องจริงๆ ที่สามารถสลับไปใช้อาวุธระยะประชิดต่อสู้กับอิคลิพไซท์หลายตัวได้โดยสัญชาตญาณเป็นวิธีที่ดีที่สุด.",
  ui_story_5083_50830801_75_dialog_content = "คุณกำลังรู้สึกตัวใช่มั้ย บาร์ตัน?",
  ui_story_5083_50830801_76_dialog_content = "ไม่จริงนะ; ผู้บัญชาการคนเก่าได้ฝึกสัญชาตญาณบางอย่างให้ฉัน และฉันกำลังเห็นมันทำงานครั้งแรก ฮ่า, ฉันเริ่มรู้สึกเหมือนอยู่บ้านในการต่อสู้แบบนี้",
  ui_story_5083_50830801_77_dialog_content = "เราจะไม่สามารถยืนหยัดที่ตำแหน่งนี้ได้นานแล้ว ฉันแนะนำให้คุณนำทีมไปพยายามตัดทางหลบหนีผ่านศัตรู มันคือโอกาสที่ดีที่สุดในการนำคนเหล่านี้กลับไปที่เมืองแกนน่อน",
  ui_story_5083_50830801_78_dialog_content = "แล้วเธอล่ะ? อย่าบอกฉันว่าเธอจะอยู่ที่นี่?",
  ui_story_5083_50830801_79_dialog_content = "ฉันบอกพวกเขาว่าฉันจะสู้รับมันไปด้วยกันจนถึงสุดท้าย... ถ้าเราป้องกันเมืองใต้ดินไม่ได้ เราจะระเบิดมันและตรวจสอบให้แน่ใจว่าอิคลิพไซท์ไม่สามารถใช้มันในทางใดทางหนึ่งได้",
  ui_story_5083_50830801_80_dialog_content = "ไม่มีทางเกิดขึ้นแบบนั้น ไรน์ฮาร์ต! ผู้บัญชาการแพ็งโก้ได้ให้คำมั่นว่าเขาจะมา และเขาไม่เคยผิดสัญญา!",
  ui_story_5083_50830801_81_dialog_content = "... เราไม่มีทางสื่อสารกับใครนอกเมืองได้ และไม่มีผู้ส่งข้อความของเราที่กลับมา เธอจริงๆ ไว้ใจเขามากขนาดนั้นหรือ บาร์ตัน?",
  ui_story_5083_50830801_82_dialog_content = "เขาอาจจะเป็นคนที่ไม่ดี แต่ชายชรานั้นไม่เคยโกหกฉันมาก่อน... ดังนั้นแน่นอนฉันเชื่อ! ฉันเชื่อเขาเหมือนฉันเชื่อคุณที่จะคอยคุ้มครองฉัน!",
  ui_story_5083_50830801_83_dialog_content = "แล้วฉันก็ไม่มีเหตุผลที่จะสงสัยเขาเช่นกัน!",
  ui_story_5083_50830801_84_dialog_content = "ฮืม. เพื่ออิลลูมินาและพวกเราทหารที่ตกสู้... ฉันปฏิเสธที่จะยอมแพ้ให้อิคลิพไซท์หรือหนีอย่างอับอาย.",
  ui_story_5083_50830801_85_dialog_content = "แล้วเราจะยืนหลังหากัน และสู้จนถึงขั้นทุกความหวังสูญหายไป!",
  ui_story_5083_50830801_86_dialog_content = "อิคลิพไซท์ขนาดใหญ่กำลังเข้ามา ไรน์ฮาร์ต! ฉัน...ฉันคิดว่ามันอาจจะเป็นผู้นำของพวกเขา!",
  ui_story_5083_50830801_87_dialog_content = "ทหารน้อยนิดของอิลลูมินา - หักเข่าลงต่อฉัน ดัสค์คอลเลอร์ที่ไม่สามารถหยุดได้!",
  ui_story_5083_50830801_88_dialog_content = "อิคลิพไซท์ที่สามารถพูดได้หรือ? คุณไม่ได้เห็นสิ่งแบบนี้ทุกวัน... ขอโทษนะเพื่อน แต่ขาของฉันไม่ค่อยจะยอมหักความเคารพ ถ้านั่นเป็นปัญหา คุณสามารถมาเจรจากับดาบของฉันได้",
  ui_story_5083_50830801_89_dialog_content = "พวกเราไม่ใช่ประเภทที่จะยอมแพ้ ดังนั้นเพียงประหยัดมันไว้ ฉันจะให้หอกทะลุดาวของฉันแสดงให้คุณเห็นแสงจริงของอิลลูมินา!",
  ui_story_5083_50830801_90_dialog_content = "ฉันเคยเห็นแม่ล่าดาวบนท้องฟ้ายามค่ำคืน ถูกดึงดูดโดยความต้องการที่ไม่สามารถขัดขืนได้",
  ui_story_5083_50830801_91_dialog_content = "ออโรเรียนที่น่าสมเพชอยู่เพียงแค่รอดชีวิตในความมืดของนรกลึก แล้วก็ยังกล้าที่จะกระทำอย่างไม่มีความกลัวผิด",
  ui_story_5083_50830801_92_dialog_content = "แสงจะสิ้นสุดจากที่นี่เร็ว ๆ นี้... และเมืองแกนนอนจะมีชะตาที่คล้ายคลึงกัน แสงจริง ๆ ของอิลลูมินาเป็นเพียงล้อเลียน...",
  ui_story_5083_50830801_93_dialog_content = "เฮ้ ไรน์ฮาร์ต ดูเหมือนว่าเรามีนักกวีอยู่ที่นี่นะ",
  ui_story_5083_50830801_94_dialog_content = "ไม่ว่าคุณจะคิดว่าตัวเองมีวัฒนธรรมเพียงใด... คุณก็ไม่มีวันเข้าใจ สัตว์ประหลาด.",
  ui_story_5083_50830801_95_dialog_content = "วันหนึ่ง เราจะได้ปีนขึ้นจากหลุมขุดนี้และกลับสู่แอสตราที่สงบสุข—นั่นจะเป็นจุดเริ่มต้นใหม่ของเรา และโอกาสให้เราได้ตามติดแสงอีกครั้ง",
  ui_story_5083_50830801_96_dialog_content = "อิลลูมินาคือดอว์นที่ทะลุความมืดและประกาศแสงแห่งวันใหม่! ศรัทธาของเราทำให้เราสามัคคี และด้วยศรัทธาของเราคุณจะถูกหยุด!",
  ui_story_5083_50830801_97_dialog_content = "เราทั้งหมดคือเปลวไฟ... แสงประกายของอิลลูมินาที่เจิดจรัส! คุณจะไม่มีโอกาสสิ้นสุดแสงสว่างของเราเลย!",
  ui_story_5083_50830801_98_dialog_content = "ไม่มีวิธีที่จะพูดได้ดีกว่านี้! ไม่ว่าคุณจะโยนอิคลิพไซท์มากมายเท่าไร คุณก็ไม่สามารถทำลายจิตใจของเราได้!",
  ui_story_5083_50830801_99_dialog_content = "ฉันจะทำให้คุณชดใช้ความโอหังของคุณอย่างแพงมาก, คนอ่อนแอ—โจมตี!",
  ui_story_5083_50830801_100_dialog_content = "<color=#e8d9bb>ตูม!</color>",
  ui_story_5083_50830801_101_dialog_content = "<color=#e8d9bb>กระสุนปืนใหญ่เชื่อมต่อกับ Eclipsite อย่างกะทันหันและระเบิด ทำให้มันสะเทือน</color>",
  ui_story_5083_50830801_102_dialog_content = "<color=#e8d9bb>เสียงแตรดังขึ้นเมื่อระบบออกอากาศฉุกเฉินของเมืองใต้ดินหมายเลข 19 เริ่มทำงาน ส่งสัญญาณแสดงถึงการมาถึงของกำลังสำรองที่รอคอยมานาน</color>",
  ui_story_5083_50830801_103_dialog_content = "<color=#e8d9bb>ทหารหันหน้าที่เปื้อนด้วยเลือดไปทางขอบฟ้า อาบแสงสว่าง, กองทัพทั้งหมดปรากฏขึ้นและเริ่มการเดินทางบุกต่อศัตรู</color>",
  ui_story_5083_50830801_104_dialog_content = "<color=#e8d9bb>ธงของกองพลที่ 2 ปลิวขึ้นเหนือหัวของพวกเขา—เป็นสัญลักษณ์ของพลังแห่งรุ่งอรุณ</color>",
  ui_story_5083_50830801_105_dialog_content = "ความทะนงนี้... กล้าดียังไงถึงมาโจมตีฉัน พวกออโรเรียนโง่เง่า! คุณจะต้องชำระด้วยเลือดของคุณ—",
  ui_story_5083_50830801_106_dialog_content = "โอกาสของเรามาถึงแล้ว ไรน์ฮาร์ต! จู่โจม!",
  ui_story_5083_50830802_1_dialog_content = "ฟอสเฟอรัส... ไม่! ทุกคนต้องตายที่นี่! แอสตราถูกกำหนดให้ทุกข์ทรมานไปอย่างไม่มีที่สิ้นสุด... คืนที่นิรันดร์จะไม่ถูกหยุดยั้ง!",
  ui_story_5083_50830802_2_dialog_content = "ขออภัย แต่การเอาชนะความชั่วร้ายก็เป็นชะตากรรมของทุกฮีโร่ในเรื่องราวแบบนี้เช่นกัน",
  ui_story_5083_50830802_3_dialog_content = "ฉันล้มเหลวหรือ? ไม่! นี่ไม่ได้—",
  ui_story_5083_50830802_4_dialog_content = "ไม่มีทางหนีพ้นจากความทำลายของคุณ... เสียงระฆังเริ่มต้นการสั่น... ชั่วโมงของ<color=#FFB400>ความตาย</color>ของคุณกำลังจะมาถึง...",
  ui_story_5083_50830802_5_dialog_content = "พี่ชายของฉัน... จะต้องดำเนินงานที่ยิ่งใหญ่ของฉันต่อไป... อ๊าก! <color=#FFB400>แม่</color>...",
  ui_story_5083_50830802_6_dialog_content = "เขาพูดอะไรกันอยู่น่ะ? ดูเหมือนว่ายังมีศัตรูที่แข็งแกร่งอีกคนรออยู่ข้างนอก...",
  ui_story_5083_50830802_7_dialog_content = "ฉันไม่แน่ใจเต็มที่... แต่เราก็รอดมาได้ นั่นละที่สำคัญ",
  ui_story_5083_50830802_8_dialog_content = "แผนกที่สาม รีบทำงานเกี่ยวกับการกู้คืนสถานีไฟฟ้า! สร้างการสื่อสารใหม่และส่งข้อความกลับไปยังเมือง Gannon... ไม่ ส่งไปยังทุกเมืองใต้ดินในสหพันธ์!",
  ui_story_5083_50830802_9_dialog_content = "บอกพวกเขาว่าเมืองนี้ยังมีโอกาสรอดได้ และอย่ายอมแพ้!",
  ui_story_5083_50830802_10_dialog_content = "คุณบาร์ตันคะ เราเพิ่งได้รับการส่งเร่งด่วนจากเมืองใต้ดินหมายเลข 13! โปรดฟังนะคะ!",
  ui_story_5083_50830802_11_dialog_content = "... เจ้าหน้าที่สื่อสารของฉันบอกว่าเมืองใต้ดินหมายเลข 19 ปลอดภัยแล้ว นั่นเป็นผลงานของคุณแพ็งโก้หรือเปล่า?",
  ui_story_5083_50830802_12_dialog_content = "ขอโทษนะ เพื่อนรัก... ฉันไม่สามารถช่วยคุณด้วยตัวเองได้",
  ui_story_5083_50830802_13_dialog_content = "หึหึ, ไม่ต้องขอโทษ นี่เป็นตัวเลือกที่ดีที่สุดใช่ไหม? ดูแลที่นั่นดีๆ และตรวจสอบให้แน่ใจว่าเราจะไม่ทำให้มันหายอีกครั้ง",
  ui_story_5083_50830802_14_dialog_content = "นายทหารหนุ่มที่น่าทึ่งนั่น... วราธ ถ้าฉันไม่ผิดพลาด? เธอกำลังนำทุกคนออกจากที่หลบภัยในขณะนี้",
  ui_story_5083_50830802_15_dialog_content = "อะไร?! ผู้บัญชาการแพ็งโก้ ให้ฉันนำทีมไปช่วยเธอที่นั่น!",
  ui_story_5083_50830802_16_dialog_content = "เขาพูดถูก! ฉันคิดว่ายังมีความหวังในการช่วยเหลือเมืองใต้ดินหมายเลข 13—",
  ui_story_5083_50830802_17_dialog_content = "เงียบซะ ทั้งสองคน! ให้ผู้ชายคนนี้พูดจบก่อน!",
  ui_story_5083_50830802_18_dialog_content = "เราได้ต่อสู้โดยไม่มีการพักผ่อนในช่วงสิบห้าวันที่ผ่านมา... นอกจากฉันแล้ว ทหารของเราทั้งหมดก็ได้ล้มลงแล้ว",
  ui_story_5083_50830802_19_dialog_content = "แต่เมื่อได้ยินว่าเมืองใต้ดินหมายเลข 19 ปลอดภัย ใจฉันก็สงบลง",
  ui_story_5083_50830802_20_dialog_content = "คุณไม่ได้อพยพเหรอ?",
  ui_story_5083_50830802_21_dialog_content = "เมืองใต้ดินหมายเลข 13 กำลังจะพัง และมีคนต้องเริ่มต้นการทำลายตัวเอง... ถ้าทางไปเมืองแกนนอนถูกปิด การพังทลายก็จะถูกป้องกันไว้ได้",
