  ui_story_5083_50831400_23_dialog_content = "นี่คือครั้งที่สองที่คุณออกจากแกนน่อนด้วยหน่วยกลไก! คุณโชคดีที่จอมทัพยังไม่ได้ลงมาตีคุณ!",
