  ui_story_5083_50831400_78_dialog_content = "<color=#e8d9bb>เขาสุดท้ายก็เดินออกไปด้วยก้าวที่หนักหน่วง เพื่อให้ทางให้บาร์ตัน</color>",
  ui_story_5083_50831400_79_dialog_content = "ชื่อของทุกทหารถูกเพิ่มแล้ว นี่คือสถานที่พักผ่อนสุดท้ายสำหรับลูกเล็กเด็กแดงทั้งหมดของอิลลูมินา",
