  ui_story_5083_50831601_26_dialog_content = "รอสักครู่... ฉันโดนตบที่ขากรรไกรแล้วไม่รู้สึกเจ็บเลยเหรอ?",
  ui_story_5083_50831601_27_dialog_content = "อย่ายืนอยู่เฉยๆ, สู้ต่อไป!",
  ui_story_5083_50831601_28_dialog_content = "ข้ามศพฉันไปก่อนเถอะ!",
  ui_story_5083_50831601_29_dialog_content = "มันต้องเป็นความฝัน ฉันไม่มีกรามเหล็กตอนยังเด็ก",
  ui_story_5083_50831601_30_dialog_content = "...เข้าใจแล้ว... นี่คือฝันร้ายที่ฉันตกอยู่ในนั้น",
