  ui_story_5083_50831601_33_dialog_content = "ฉันหลงทาง... แต่ฉันเชื่อเสมอว่าถ้าฉันยังคงสู้ต่อไป แสงสว่างจะส่องสว่างหน้าฉัน",
  ui_story_5083_50831601_34_dialog_content = "แต่คุณยังคงติดอยู่ที่นี่",
  ui_story_5083_50831601_35_dialog_content = "ฉันไม่รู้นะ ฉันจำอะไรไม่ได้เลย... ฉันไม่คิดว่าฉันจะหนี แต่ฉันจำไม่ได้ว่าฉันทำอะไรหลังจากนั้น...",
