  ui_story_5083_50831601_48_dialog_content = "สำหรับฉันที่สามารถมองเห็นแสงสว่างแต่ไม่สามารถสัมผัสได้ เส้นทางนั้นอยู่ใต้เท้าคุณตลอดเวลาที่ฉันรู้จักคุณ",
