  ui_story_5083_50831601_53_dialog_content = "<size=45>Damn it!</size>",
  ui_story_5083_50831601_54_dialog_content = "<color=#e8d9bb>ด้วยเสียงกรีดร้อง บาร์ตันทำลายกุญแจมือลง</color>",
  ui_story_5083_50831601_55_dialog_content = "ถูกต้อง ฉันคือแกะดำ ผู้มีศักดิ์ศรี \"ชั้นสูง\" ที่ฝ่าฝืน!",
  ui_story_5083_50831601_56_dialog_content = "ทำไมฉันต้องทนสิ่งนี้ด้วย?",
  ui_story_5083_50831601_57_dialog_content = "ฉันกำลังเริ่มการปฏิวัติและเวลาคือตอนนี้!",
  ui_story_5083_50831601_58_dialog_content = "ทุกคนในกองพลที่ 2!",
  ui_story_5083_50831601_59_dialog_content = "ผู้พันบาร์ตัน? ภารกิจของเราคือการพาคุณไปยังที่ปลอดภัย กรุณาอย่าทำให้เรายากลำบาก",
