  ui_story_5083_50831601_75_dialog_content = "บริษัท, เริ่มต้นใหม่! มาจบคืนนี้... มาเริ่มต้นกันนอนใหม่!",
  ui_story_5083_50831601_76_dialog_content = "<color=#e8d9bb>ดังนั้นทหารก็หันกลับและเดินทางไปที่แกนน่อน</color>",
  ui_story_5083_50831601_77_dialog_content = "<color=#e8d9bb>พวกเขาทั้งหมดรู้ว่าพวกเขาจะต้องตายที่นั่น แต่ไม่มีใครลดความเร็วลง</color>",
  ui_story_5083_50831601_78_dialog_content = "<color=#e8d9bb>หากไม่มีแสงสว่างของพวกเขา ก็จะไม่มีดอว์นในอัสตรา</color>",
  ui_story_5083_50831601_79_dialog_content = "<color=#e8d9bb>วิกฤตดาร์กโอเวอร์ที่ทรมานแผ่นดินนี้มาแล้วแปดปี อาจจะสิ้นสุดลงเพราะความแข็งแกร่งของผู้ที่มาก่อน ในฐานะผู้สืบทอด มันเป็นหน้าที่ของฉันที่จะทำต่อไปจนถึงสิ้นสุด</color>",
  ui_story_5083_50831601_80_dialog_content = "ทหารของคุณถูกทำลายลง ออโรเรียนที่ไม่มีความสำคัญ ชีวิตทั้งหมดจะต้องสิ้นสูญหน้าผม <color=#FFB400>กระดิ่งวันสิ้นโลก</color>",
