  ui_story_5083_50831601_82_dialog_content = "<color=#e8d9bb>ศัตรูขนาดยักษ์เข้าใกล้หอคอยกลาง ผิวหนังหินที่เต็มไปด้วยเปลวไฟถูกปกคลุมด้วยชิ้นส่วนของโลหะเก่าๆที่น่าเกลียดเป็นเกราะ</color>",
  ui_story_5083_50831601_83_dialog_content = "<color=#e8d9bb>ใครก็ตามที่ตรวจสอบแสตมป์บนเศษซากเหล่านี้ก็จะรู้ว่าพวกมันมาจากเมืองใต้ดินที่ต่างกัน พวกมันเป็นสัญลักษณ์แสดงถึงชัยชนะของสัตว์ประหลาดเหมือนเหรียญที่เกียรติยศ</color>",
  ui_story_5083_50831601_84_dialog_content = "<color=#e8d9bb>มันน่าขนลุกและน่าโกรธในเวลาเดียวกันอย่างน่าขนลุก</color>",
  ui_story_5083_50831601_85_dialog_content = "<color=#e8d9bb>ขณะที่มันก้าวไปข้างหน้า, ชิ้นส่วนที่เหลือทับซ้อนกันเป็นเสียงแครงที่หม่นหมองเหมือนกับการระฆังเพลงเรเควียมที่เต็มไปด้วยความเกลียดชัง.</color>",
  ui_story_5083_50831601_86_dialog_content = "อ๊ะ คุณกำลังสั่นเลยนะ เจ้าจิ๋ว ใช่ ฉันสามารถรับรู้ความกลัวของคุณได้ แม้แต่ธงที่คุณถืออยู่ก็กำลังสั่นไหว.",
  ui_story_5083_50831601_87_dialog_content = "แมลงศัตรูทั้งหมดนั้นเหมือนกัน พวกมันกลัวคนที่แข็งแกร่ง นั่นคือสัญชาตญาณของมัน คุกเข่าให้ฉันทำลายคุณด้วยความสุข",
  ui_story_5083_50831601_88_dialog_content = "อืม, ผมกำลังสั่น... ผมไม่คิดว่าจะกลัวขนาดนี้ในวัยนี้นะ.",
  ui_story_5083_50831601_89_dialog_content = "อาจจะเป็นสัญชาตญาณนะ ดังที่คุณพูด",
  ui_story_5083_50831601_90_dialog_content = "ยอมรับแล้วเหรอ? แล้วก็คุกเข่าและขอความเมตตาสิ! นี่คือความสุขที่สุดของฉัน.",
  ui_story_5083_50831601_91_dialog_content = "เธอหยอกหรอ ไอ้ตัวเฉิ่ม? เธอคิดว่าเธอกำลังเผชิญหน้ากับพวกขี้ขลาดหรอ?",
  ui_story_5083_50831601_92_dialog_content = "คุณไม่รู้เลยว่าคุณต่างจากเรายังไง!",
  ui_story_5083_50831601_93_dialog_content = "คุณจะไม่มีความสุขใด ๆ ทั้งสิ้น ที่คุณจะเห็นเพียงแค่ว่ากระดูกสันหลังของคนอิลลูมินามันแข็งแกร่งเพียงใด!",
  ui_story_5083_50831601_94_dialog_content = "ออโรเรียนมีความกลัว แต่อิคลิพไซท์ก็เช่นกัน และคุณจะไม่เคยเรียนรู้วิธีรับมือกับมันเหมือนพวกเรา",
  ui_story_5083_50831601_95_dialog_content = "ฉันบอกว่าไม่... ไม่มีทางคุณจะข้ามเส้นของเราได้!",
  ui_story_5083_50831601_96_dialog_content = "ถ้างั้นฉันจะทดสอบมัน",
  ui_story_5083_50831601_97_dialog_content = "ขอโทษครับท่าน นี่คือสิ่งที่ดีที่สุดที่เราทำได้... ทำไมความช่วยเหลือยังไม่มาถึง...?",
  ui_story_5083_50831601_98_dialog_content = "ฉันเห็นว่าได้เวลาหลอกลวงทหารของคุณแล้ว ไปเถอะ แสดงลูแมมเบอร์และบอกพวกเขาว่าความช่วยเหลือกำลังจะมาถึง",
  ui_story_5083_50831601_99_dialog_content = "นั่นคือความเท็จที่ทุกๆ ผู้บังคับบัญชาในทุกๆ เมืองใต้ดินที่ฉันทำลาย...",
  ui_story_5083_50831601_100_dialog_content = "ไม่มีความช่วยเหลือมาถึงแม้ฉันจะดึงลมหายใจสุดท้ายออกจากพวกเขา มันเป็นความปลอมประกอบที่ไร้สาระที่สุดสำหรับอิลลูมินา",
  ui_story_5083_50831601_101_dialog_content = "ฉันขอโทษนะ พวกเพื่อน คุณไว้วางใจให้ฉันดูแลชีวิตของคุณ แต่ฉันก็ไม่สามารถสัญญาอะไรเป็นแลกและตอบแทนได้",
  ui_story_5083_50831601_102_dialog_content = "แต่โปรดเชื่อฉันเมื่อฉันบอกว่าอิลลูมินาจะไม่เคยทอดทิ้งผู้ป้องกันของมัน!",
  ui_story_5083_50831601_103_dialog_content = "<color=#e8d9bb>แพ็งโก้ปล่อยลูมแอมเบอร์และดึงระดับลงในการสวดมนต์ แสงสว่างโค้งขึ้นมาทั่วที่มืดมิดที่แกนน่อนล้มลงและลงไปในท้องฟ้า</color>",
  ui_story_5083_50831601_104_dialog_content = "<color=#e8d9bb>ทหารที่ต่อสู้อย่างหนักใน Gannon มองไปที่แสงแฟลชด้วยความสามัคคี ด้วยการสะท้อนของ </color><color=#FFB400>ความหวัง</color><color=#e8d9bb> ที่ส่องสว่างในดวงตาของพวกเขา</color>",
  ui_story_5083_50831601_105_dialog_content = "คุณอยู่คนเดียว แต่คุณยังหลอกลวงตัวเองและเรียกมันว่าศรัทธา ดีใจนะ การทำลายนักรบที่มีศรัทธานั้นสนุกกว่าการทำลายแมลงศัตรูที่ธรรมดาเยอะแยะ!",
  ui_story_5083_50831601_106_dialog_content = "คุณ...อิคลิพไซท์ นี่เป็นเหตุผลว่าทำไมคุณจะไม่เคยได้มัน... พวกเราทหารแห่งอิลลูมินาถูกเรียกว่า \"ผู้ป้องกันแห่งอัสตรา\" ด้วยเหตุผล!",
  ui_story_5083_50831601_107_dialog_content = "ฉันคือ ซิวร์ตัน จำชื่อนี้ไว้ เป็นชื่อของผู้ทำลายของคุณ!",
  ui_story_5083_50831601_108_dialog_content = "ฆ่าพวกเขาทั้งหมด ทำลายหอคอยกลาง ฉันต้องการให้ Gannon ถูกทำลายลงสู่ความลืม.",
  ui_story_5083_50831601_109_dialog_content = "กองพลที่ 2 ไม่เคยถอยหลัง!",
  ui_story_5083_50831601_110_dialog_content = "<color=#e8d9bb>สัญญาณในท้องฟ้าค่อย ๆ สลายลง และสุดท้ายก็หายไป ความหวังทั้งหมดดูเหมือนจะสูญหายไปในความมืดมิด</color>",
  ui_story_5083_50831601_111_dialog_content = "กองพลที่ 2? ฉันได้ยินเรื่องนี้เมื่อไม่กี่วันที่ผ่านมา พวกเขายังทำให้ฉันถูกตัดที่หัวและหลังอีกด้วย",
  ui_story_5083_50831601_112_dialog_content = "เสียดายที่เขาและทหารของเขาน่าสงสาร แต่ฉันได้เก็บดาบของเขาไว้ ดูนี่สิ ไม่ใช่ที่ระลึกที่ไม่ดีนะ",
  ui_story_5083_50831601_113_dialog_content = "ด็อกก์! ฉันขอโทษ...",
  ui_story_5083_50831601_114_dialog_content = "<color=#e8d9bb>เต็มไปด้วยความสิ้นหวัง ทหารเก่าแก่จับอาวุธของพวกเขาและเตรียมตัวเพื่อวิ่งชนกับองค์ที่ยักษ์ใหญ่</color>",
  ui_story_5083_50831601_115_dialog_content = "<color=#e8d9bb>แต่ดวงดาวก็ยังส่องสว่างที่สุดในความมืดที่สุดของคืน</color>",
  ui_story_5083_50831601_116_dialog_content = "<size=45>ไกลพอแล้ว!</size>",
  ui_story_5083_50831601_117_dialog_content = "<size=45>ลองใส่นี่ดูสิ!</size>",
  ui_story_5083_50831601_118_dialog_content = "คุณนี่แหละที่ขุดหลุมฝังตัวเอง คุณโง่เศร้า!",
  ui_story_5083_50831601_119_dialog_content = "<color=#e8d9bb>ยานพาหนะเกราะลงมาและชนเข้ากับหลังของ Eclipsite ที่ยิ่งใหญ่ โดยที่ป้อมปืนทำความเสียหายสูงสุดในระยะใกล้เช่นนี้</color>",
  ui_story_5083_50831601_120_dialog_content = "หวาา!",
  ui_story_5083_50831601_121_dialog_content = "ฉันจับเธอได้แล้ว... โอ๊ย!",
  ui_story_5083_50831601_122_dialog_content = "ขอบคุณนะ เพื่อน!",
  ui_story_5083_50831601_123_dialog_content = "นี่มันตลกที่สุด ระเบิดยานพาหนะ! แล้วคุณก็เกือบจะ...",
  ui_story_5083_50831601_124_dialog_content = "ถ้าไม่มีความบ้า ก็ไม่ใช่ฉัน ใช่ไหม?",
  ui_story_5083_50831601_125_dialog_content = "นี่คือตัวฉันที่แท้จริง คุณเห็นมั้ย!",
  ui_story_5083_50831601_126_dialog_content = "คุณกลับมาทำอะไรที่นี่ คุณโง่เนี่ย?!",
  ui_story_5083_50831601_127_dialog_content = "คุณไม่ได้ส่งสัญญาณ SOS หรือไงคะ? แล้วฉันไม่ถือเป็นกำลังเสริมที่ถูกต้องหรือไงคะ?",
  ui_story_5083_50831601_128_dialog_content = "ด้านบนได้พังลงมาแล้ว ฉันมาที่นี่ด้วยยานพาหนะ และตอนนี้ฉันไม่มีทางกลับแม้ว่าคุณจะไม่ต้องการฉันอยู่ที่นี่",
  ui_story_5083_50831601_129_dialog_content = "อะไรกัน...!",
  ui_story_5083_50831601_130_dialog_content = "นี่เป็นครั้งที่สามแล้วนะ! อย่าบอกฉันให้ออกไปอีกล่ะ ชายชรา!",
  ui_story_5083_50831601_131_dialog_content = "ฉันมีข้อความสำหรับอิคลิพไซท์: แม้จะอยู่ในที่ลึกลับที่คุณไม่เห็นแสงแดด พวกเขาก็ยังไม่ได้เป็นเจ้าของที่นั่น!",
  ui_story_5083_50831601_132_dialog_content = "แกนน่อนจะสว่างสดใสอีกครั้ง แน่นอน!",
  ui_story_5083_50831601_133_dialog_content = "โง่เว้ย, ก่อนที่ความช่วยเหลือจะมาถึง เราคงตายก่อนแน่!",
  ui_story_5083_50831601_134_dialog_content = "ในกรณีนั้น ฉันหวังว่าแสงจากประภาคารจะส่องสว่างบนร่างกายของเรา",
  ui_story_5083_50831601_135_dialog_content = "แรงระเบิดเกือบทำให้ฉันตกจากขอบ, ศัตรูเลว.",
  ui_story_5083_50831601_136_dialog_content = "อะไร? ยังอยู่ในสองชิ้นแต่ยังไม่ตายเหรอ?",
  ui_story_5083_50831601_137_dialog_content = "คุณคิดว่าฉันจะถูกฆ่าด้วยการระเบิดเพียงเล็กน้อยหลังจากที่ทำลายเมืองใต้ดินเยอะแยะไปแล้วหรือ? ฉันคือ <color=#FFB400>เนเมซิสของทุกสิ่งที่มีชีวิต</color>!",
  ui_story_5083_50831601_138_dialog_content = "นั่นตลกนะ ที่เรียกตัวเองว่าเป็นศัตรูของทุกสิ่งที่มีชีวิต แต่กลับมีชีวิตอยู่ตลอดเวลา",
  ui_story_5083_50831601_139_dialog_content = "หุบปากแล้วลุยกันเถอะ!",
  ui_story_5083_50831601_140_dialog_content = "เธอรอดูเถอะ จนกว่าฉันและพวกเราจะส่งเธอไปนรก!",
  ui_story_5083_50831602_1_dialog_content = "คุณฆ่าฉันไม่ได้!",
  ui_story_5083_50831602_2_dialog_content = "เฮ้ พูดถึงกระดูกสันหลังที่ไม่หัก... ฉันไม่เห็นคุณลุกขึ้นเลยนะ",
  ui_story_5083_50831602_3_dialog_content = "หนอย! ไปลงนรกซะ!",
  ui_story_5083_50831602_4_dialog_content = "คุณก็สามารถไปที่นั่นด้วยเขาได้เหมือนกัน!",
  ui_story_5083_50831602_5_dialog_content = "<color=#e8d9bb>บาร์ตันหลบหน้าที่มือแล้ววิ่งขึ้นไปที่แขนของสัตว์</color>",
  ui_story_5083_50831602_6_dialog_content = "<color=#e8d9bb>ก่อนที่ซิวร์ตันจะได้ตอบสนอง มันดึงถ้วยรางวัล—มีดของด็อก—ออก</color>",
  ui_story_5083_50831602_7_dialog_content = "<color=#e8d9bb>ดาบสองเล่มรวมเป็นหนึ่งในมือของบาร์ตันและกลายเป็นของเขา เขาหลบและโจมตีซิวร์ตันอย่างไม่ยั้งยืน</color>",
  ui_story_5083_50831602_8_dialog_content = "<color=#e8d9bb>ในขณะระยะเดียว คอของซิวร์ตันถูกตัดเปิด ทำให้มันต้องสะบัดและปล่อยไฟออกมา</color>",
  ui_story_5083_50831602_9_dialog_content = "<color=#e8d9bb>แต่บาร์ตันก็ยังคงตัดต่อไปในขณะที่เปลวไฟพุ่งออกมา การโจมตีที่ไม่มีที่ติเป็นผลมาจากการฝึกฝนอย่าง</color><color=#FFB400> ไม่รู้จบ </color><color=#e8d9bb> ในฐานทัพ</color>",
  ui_story_5083_50831602_10_dialog_content = "<color=#e8d9bb>และสิ่งที่น่ากลัวยิ่งขึ้นคือการจ้องมองอันเต็มไปด้วยความต้องการฆ่าในดวงตาของบาร์ตัน</color>",
  ui_story_5083_50831602_11_dialog_content = "<color=#e8d9bb>เขากระโดดผ่านไฟ แยกความมืดและแทงดาบลึกลงในคอของซิวร์ตัน</color>",
  ui_story_5083_50831602_12_dialog_content = "ออกจากฉัน!",
  ui_story_5083_50831602_13_dialog_content = "อย่าคิดเลยว่าจะทำร้ายผู้นำบาร์ตัน! ยิงที่ตา!",
  ui_story_5083_50831602_14_dialog_content = "นี่คือจุดจบ... และนี่คือวิธีที่ฉันใช้ปืนครับ!",
  ui_story_5083_50831602_15_dialog_content = "<color=#e8d9bb>บาร์ตันดึงปืนและยิง กระสุนปักเข้าไปในดาบคู่และฝังอยู่ในซิวร์ตันอย่างสมบูรณ์</color>",
  ui_story_5083_50831602_16_dialog_content = "<color=#e8d9bb>เขาจึงกดรีโมทเพื่อบ่งบอกว่าเขาได้วางวัตถุระเบิดที่เขาฝังไว้ในดาบของเขา</color>",
  ui_story_5083_50831602_17_dialog_content = "<color=#e8d9bb>ไม่มีใครจะคิดได้ว่าบาร์ตันจะสละอาวุธของเขาและเพื่อนสนิทเพื่อความชนะ</color>",
  ui_story_5083_50831602_18_dialog_content = "ไม่! <color=#FFB400>แม่</color>...",
  ui_story_5083_50831602_19_dialog_content = "สนุกกับความอับอายของคุณในนรกสิ ไอ้งี่เง่า",
  ui_story_5083_50831602_20_dialog_content = "คุณแน่ใจหรือว่าสิ่งนี้ดี?",
  ui_story_5083_50831602_21_dialog_content = "ด็อกก์จะอยู่ในหัวใจพวกเราและบนอนุสาวรีย์ตลอดไป",
  ui_story_5083_50831602_22_dialog_content = "ความมุ่งมั่นของเขาเพียงพอที่จะพาเราก้าวหน้า ไม่มีอะไรที่จำเป็นอีกต่อไป",
  ui_story_5083_50831602_23_dialog_content = "โอ้ ไม่เป็นไรนะ ผู้บัญชาการแพ็งโก้?",
  ui_story_5083_50831602_24_dialog_content = "อย่าแตะเขา การตบนั้นทำให้กระดูกสันหลังของเขาหัก",
  ui_story_5083_50831602_25_dialog_content = "ระวังนะ คอลเนลบาร์ตัน อิคลิพไซท์ขนาดเล็กยังคงเคลื่อนไหวอยู่!",
  ui_story_5083_50831602_26_dialog_content = "ระมัดระวัง... ธงของกองพลที่ 2... คุณคือผู้บัญชาการตอนนี้ บาร์ตัน... นำทหาร... และสู้จนหายใจสุดท้าย...",
  ui_story_5083_50831602_27_dialog_content = "เชื่อ... ในพี่น้องชาว Illumina... ความช่วยเหลือจะมา...",
  ui_story_5083_50831602_28_dialog_content = "เขาออกไปแล้ว!",
  ui_story_5083_50831602_29_dialog_content = "หนอย, หนอย!",
  ui_story_5083_50831602_30_dialog_content = "กองพลที่ 2 จะไม่ยอมทำความสะอาด!",
  ui_story_5083_50831602_31_dialog_content = "The 2nd Legion will never compromise!",
  ui_story_5083_50831602_32_dialog_content = "<color=#e8d9bb>อิคลิพไซท์ขนาดยักษ์ตายไปแล้ว แต่การต่อสู้ยังคงต่อไป อิคลิพไซท์ขนาดเล็กๆ รุมโจมทางเดียวที่เข้าไปและต่อสู้กับทหาร</color>",
  ui_story_5083_50831602_33_dialog_content = "<color=#e8d9bb>ด้วยธงที่ถืออยู่ในมือ บาร์ตันได้ร่วมสู้กับนักรบจนกระทั่งหลังของพวกเขาอยู่ที่สถานีผลิตไฟฟ้า</color>",
  ui_story_5083_50831602_34_dialog_content = "<color=#e8d9bb>เมื่อเขามองรอบๆ พบว่ามีผู้ชายเพียงไม่กี่คนที่ยังอยู่</color>",
  ui_story_5083_50831602_35_dialog_content = "นี่ห่างพอแล้ว!",
  ui_story_5083_50831602_36_dialog_content = "แม้จะเหลือแค่เรา ก็จะไม่ยอมทำข้อตกลง... ไม่มีวันทำข้อตกลง...",
  ui_story_5083_50831602_37_dialog_content = "ฉันจะต่อสู้กับคุณจนถึงช่วงสุดท้าย บาร์ตัน",
  ui_story_5083_50831602_38_dialog_content = "เราจะตามนายพลบาร์ตันไปจนถึง breath สุดท้ายของเรา",
  ui_story_5083_50831602_39_dialog_content = "เราจะตายในการป้องกันทางผ่านนี้!",
  ui_story_5083_50831602_40_dialog_content = "ฉันทำอะไรอยู่เนี่ย? ฉันโง่จริงๆ! ทำไมฉันถึงคิดถึงมันตอนนี้เนี่ย?",
  ui_story_5083_50831602_41_dialog_content = "ฉันรู้อยู่แล้วว่าสิ่งนี้จะจบยังไง",
  ui_story_5083_50831602_42_dialog_content = "ในอดีต เราถูกบังคับให้ถอยหลังจากที่เราเอาชนะอิคลิพไซท์ที่ใหญ่โตนั้นในช่วงสุดท้าย แต่แพ็งโก้ยังคงอยู่และต่อสู้",
  ui_story_5083_50831602_43_dialog_content = "ทุกคนที่อยู่กับเขาต่างเสียชีวิต และเขาเองก็ตกอยู่ในสภาพโคม่าจากบาดเจ็บมากกว่าสิบปี",
  ui_story_5083_50831602_44_dialog_content = "...",
  ui_story_5083_50831602_45_dialog_content = "ฉันไม่มีสายตาเหมือนของคุณ PlayerName ดังนั้นฉันอิจฉาที่คุณสามารถมองเห็นแสงสว่างได้ตลอดเวลา",
  ui_story_5083_50831602_46_dialog_content = "แต่ฉันไม่หลงทาง เพราะฉันเชื่ออย่างแท้จริงว่าจะมีแสงสว่างถ้าเราสู้จนถึงที่สุด",
  ui_story_5083_50831602_47_dialog_content = "เมื่อฉันพบคุณครั้งแรก คุณกำลังเดินทางบนเส้นทางของความหวังจริง ๆ",
  ui_story_5083_50831602_48_dialog_content = "ฉันรู้สึกเป็นเกียรติที่ได้รู้จักคุณ คุณคือผู้ที่ช่วยเราทั้งสองหลายครั้งไม่นับถือ",
  ui_story_5083_50831602_49_dialog_content = "คุณคือฮีโร่ แต่ถูกทรมานด้วยฝันร้าย... ฉันต้องการที่จะแนะนำคุณ...",
  ui_story_5083_50831602_50_dialog_content = "ฉันไม่กลัวหลงทางถ้ามีเธออยู่เคียงข้าง และฝันร้ายไม่ใช่อะไรสำหรับฉันเลย",
  ui_story_5083_50831602_51_dialog_content = "แต่ฉันไม่สามารถปล่อยมันไปได้...",
  ui_story_5083_50831602_52_dialog_content = "การส่งกำลังเสริมไปหาผู้บัญชาการแพ็งโก้เคยมาหรือไม่?",
  ui_story_5083_50831602_53_dialog_content = "จริงด้วย, ฉันลืมไปได้ยังไงนะ...?",
  ui_story_5083_50831602_54_dialog_content = "ผู้บัญชาการแพ็งโก้ คือ \"ฝันร้าย\" ที่แท้จริงสำหรับฉัน...",
